import * as assert from 'assert';
import { GitIntegrationService } from '../../../src/git';
import { ContextKeyController, SelectionCoordinator } from '../../../src/selection';

// Live feasibility check (#3, extended by #4): opens a real Git repository with one linked
// worktree (generated by test/setup/createGitFixture.js as this suite's workspace folder — see
// .vscode-test.mjs) and confirms the built-in Git extension actually surfaces the linked worktree
// as its own Repository (kind: 'worktree'), validating the #2 discovery pipeline end to end
// against a live git process rather than only against the mocked shapes in
// worktreeNormalization.test.ts.
//
// Finding (#3): SCM "selected" state is owned by VS Code core's Source Control view focus
// mechanism (ISCMViewService), which has no public API a test can script directly. The second
// test below therefore asserts internal consistency against whatever the live selection state is,
// rather than a specific true/false value; confirming the actual show/hide UX end to end is a
// manual Extension Development Host check. SelectionCoordinator's precedence rules themselves are
// covered deterministically against a fake in test/unit/selectionCoordinator.test.ts (#4).
suite('Live Git worktree discovery (#3 feasibility spike)', function () {
  this.timeout(30000);

  let gitIntegration: GitIntegrationService;
  let selectionCoordinator: SelectionCoordinator;
  let contextKeys: ContextKeyController;

  suiteSetup(async () => {
    gitIntegration = new GitIntegrationService();
    await gitIntegration.activate();
    // Wait for the linked and detached worktrees to appear *and* their HEAD state to settle:
    // opening a repository via the Git API returns before its status refresh (which populates
    // HEAD) completes.
    await waitUntil(() => {
      const worktrees = gitIntegration.listWorktrees();
      return worktrees.length >= 3 && worktrees.every((w) => w.ref !== undefined);
    }, 20000);
    selectionCoordinator = new SelectionCoordinator(gitIntegration);
    contextKeys = new ContextKeyController(gitIntegration);
  });

  suiteTeardown(() => {
    contextKeys.dispose();
    selectionCoordinator.dispose();
    gitIntegration.dispose();
  });

  test('FR-001/FR-002/FR-003: discovers the main repository and its linked worktree live', () => {
    const worktrees = gitIntegration.listWorktrees();
    const main = worktrees.find((w) => w.isMain);
    const linked = worktrees.find((w) => !w.isMain && w.ref === 'feature/x');

    assert.ok(main, 'main repository should be discovered');
    assert.ok(linked, 'linked worktree should be discovered');
    assert.strictEqual(linked!.repositoryRoot.fsPath, main!.rootUri.fsPath);
    assert.strictEqual(linked!.ref, 'feature/x');
    assert.strictEqual(linked!.isDetached, false);
  });

  test('§28.2 detached-worktree scenario: a detached worktree is discovered and flagged live', () => {
    const worktrees = gitIntegration.listWorktrees();
    const detached = worktrees.find((w) => !w.isMain && w.isDetached);

    assert.ok(detached, 'detached worktree should be discovered');
    assert.strictEqual(detached!.isDetached, true);
    assert.ok(detached!.ref && /^[0-9a-f]{7,40}$/.test(detached!.ref), `expected a commit sha, got "${detached!.ref}"`);
  });

  test('context keys stay consistent with the live-resolved selection', () => {
    const worktrees = gitIntegration.listWorktrees().filter((w) => !w.isMain);
    assert.strictEqual(contextKeys.values.hasWorktrees, worktrees.length > 0);
    // `visible` tracks `hasWorktrees` directly — it's no longer tied to whether
    // SelectionCoordinator has resolved an active root (the view stays shown and falls back to a
    // worktree instead of hiding; see PRD §9.4).
    assert.strictEqual(contextKeys.values.visible, contextKeys.values.hasWorktrees);

    const active = selectionCoordinator.snapshot.activeWorktreeUri;
    // If SelectionCoordinator resolved an active root from live SCM state, it must be one of the
    // discovered linked worktrees, not an arbitrary URI.
    if (active) {
      assert.ok(worktrees.some((w) => w.rootUri.toString() === active.toString()));
    }
  });
});

async function waitUntil(predicate: () => boolean, timeoutMs: number): Promise<void> {
  const start = Date.now();
  while (!predicate()) {
    if (Date.now() - start > timeoutMs) {
      throw new Error('Timed out waiting for the Git extension to discover the fixture repository.');
    }
    await new Promise((resolve) => setTimeout(resolve, 200));
  }
}
